css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .56); position: relative; overflow: hidden; border-radius: 50% 50% 6px 6px / 100% 100% 6px 6px; background: linear-gradient(color-mix(in srgb, #fff 62%, var(--accent-2)), color-mix(in srgb, #fff 34%, var(--accent-2))); }
.loader::before { content: ''; position: absolute; inset: 0; background: repeating-conic-gradient(from 180deg at 50% 100%, color-mix(in srgb, #000 40%, var(--accent-2)) 0 1.4deg, transparent 1.4deg 15deg); }
.loader::after { content: ''; position: absolute; bottom: 0; left: 50%; width: 24%; height: 72%; transform-origin: bottom left; clip-path: polygon(0 100%, 100% 100%, 64% 0, 40% 0); background: linear-gradient(to top, color-mix(in srgb, #000 48%, transparent), color-mix(in srgb, #000 8%, transparent)); animation: shadow-sweep calc(var(--loader-speed) * 4) linear infinite; }
.loader .gnomon { position: absolute; z-index: 2; bottom: 0; left: 48.5%; width: 3%; height: 76%; border-radius: 2px 2px 0 0; background: linear-gradient(var(--accent), color-mix(in srgb, #000 30%, var(--accent))); }
@keyframes shadow-sweep { 0% { transform: rotate(-76deg); } 100% { transform: rotate(76deg); } }
